/// `new WaveData()`: two waves. The first is entirely default, the second is purple to white,
/// across the wave, shifted 90 degrees and moving right to left.
fn default_waveforms() -> ParamValue {
    let first = Params::defaults(&WAVEFORM_PARAMS);
    let mut second = Params::defaults(&WAVEFORM_PARAMS);
    second.set(
        "Color",
        ParamValue::Gradient(ColorGradient::from_parts(
            vec![ColorPoint::new(Color::rgb(128, 0, 128), 0.0), ColorPoint::new(Color::rgb(255, 255, 255), 1.0)],
            vec![AlphaPoint::new(255, 0.0), AlphaPoint::new(255, 1.0)],
        )),
    );
    second.set("ColorHandling", ParamValue::Enum("Across".to_string()));
    second.set("PhaseShift", ParamValue::Int(90));
    second.set("Direction", ParamValue::Enum("RightToLeft".to_string()));
    ParamValue::RecordList(vec![first, second])
}

